const table = (widths: readonly number[]): ReadonlyMap<number, number> =>
  new Map(CODEPOINTS.map((cp, i) => [cp, Number(widths[i])]));
const mean = (widths: readonly number[]): number =>
  Math.round(widths.reduce((s, w) => s + w, 0) / widths.length);

export const INTER = {
  unitsPerEm: 2048,
  regular: table(REGULAR),
  bold: table(BOLD),
  /** Average advance, used for code points outside the table. */
  fallback: { regular: mean(REGULAR), bold: mean(BOLD) },
} as const;

export function advance(cp: number, weight: "regular" | "bold"): number {
  return INTER[weight].get(cp) ?? INTER.fallback[weight];
}
